"""
Builds benchmarks/texture_layers.bb with blitzcc and runs it once for each number of layers asked for, printing the
time per frame and what the frames cost.

    python3 benchmarks/texture_layers.py [--blitzcc PATH] [--layers 1,2,3,4] [--tiles N] [--frames N] [--size WxH]

The original Blitz3D works too (BLITZPATH is set to the folder with bin\\ in it unless it is set). Without a display
the program runs under xvfb-run (llvmpipe): the times are then only a smoke test, the counts are exact on any GPU.
"""
import argparse
import os
import platform
import re
import shutil
import sys
import tempfile
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../tools"))
import procutil  # noqa: E402

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--blitzcc")
    parser.add_argument("--layers", default="1,2,3,4")
    parser.add_argument("--tiles", type=int, default=12)
    parser.add_argument("--frames", type=int, default=int(os.environ.get("BENCH_FRAMES", 300)))
    parser.add_argument("--size", default=os.environ.get("BENCH_SIZE", "640x360"))
    args = parser.parse_args()
    compiler = args.blitzcc or shutil.which("blitzcc") or next((c for c in (os.path.join(ROOT, "build", "code_compiler", "blitzcc"), os.path.join(ROOT, "build", "code_compiler", "blitzcc.exe")) if os.path.isfile(c)), None)
    if not compiler:
        sys.exit("blitzcc not found, build it or pass --blitzcc.")
    width, height = args.size.split("x")
    version = " ".join(procutil.run([compiler, "-v"], capture_output=True, text=True).stdout.split())
    llvm = bool(re.search(r"Compiler version:20\d\d\.", version))
    if not llvm:
        os.environ.setdefault("BLITZPATH", os.path.dirname(os.path.dirname(os.path.abspath(compiler))))
    runner = [] if os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY") or platform.system() == "Windows" else ["xvfb-run", "-a", "-s", "-screen 0 %sx%sx24" % (width, height)]
    print("Compiler: %s" % version)
    with tempfile.TemporaryDirectory() as directory:
        program = os.path.join(directory, "texture_layers" + (".exe" if platform.system() == "Windows" else ""))
        source = os.path.join(directory, "texture_layers.bb")
        shutil.copy(os.path.join(HERE, "texture_layers.bb"), source)
        shutil.copy(os.path.join(HERE, "flythrough_llvm.bi" if llvm else "flythrough_original.bi"), os.path.join(directory, "flythrough_counters.bi"))
        build = procutil.run([compiler, "-q"] + (["-O3"] if llvm else []) + ["-o", program, source], cwd=directory, capture_output=True, text=True)
        if build.returncode != 0:
            sys.exit("Building the benchmark failed:\n%s" % (build.stdout + build.stderr)[-2000:])
        for layers in args.layers.split(","):
            result_file = os.path.join(directory, "result.txt")
            if os.path.isfile(result_file):
                os.remove(result_file)
            env = dict(os.environ, BENCH_LAYERS=layers, BENCH_TILES=str(args.tiles), BENCH_FRAMES=str(args.frames), BENCH_W=width, BENCH_H=height, BENCH_RESULT=result_file)
            result = procutil.run(runner + [program], env=env, capture_output=True, text=True)
            if result.returncode != 0 or not os.path.isfile(result_file):
                sys.exit("The benchmark failed (exit code %d):\n%s" % (result.returncode, (result.stdout + result.stderr)[-2000:]))
            print(open(result_file).read().strip(), flush=True)


if __name__ == "__main__":
    main()
